BEGIN;

-- 0. OPTIONAL EXTENSION (For UUIDs if needed)
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- 1. BASE TABLES DEFINITIONS (Idempotent)
CREATE TABLE IF NOT EXISTS schools (
  id VARCHAR(100) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  code VARCHAR(100) UNIQUE NOT NULL,
  center_code VARCHAR(100),
  motto TEXT,
  email VARCHAR(255) NOT NULL,
  phone VARCHAR(50) NOT NULL,
  address TEXT NOT NULL,
  logo_url TEXT,
  currency VARCHAR(20) DEFAULT 'KES',
  latitude DOUBLE PRECISION,
  longitude DOUBLE PRECISION,
  geofence_radius DOUBLE PRECISION DEFAULT 250,
  geofence_enabled BOOLEAN DEFAULT true,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS academic_years (
  id VARCHAR(100) PRIMARY KEY,
  name VARCHAR(50) NOT NULL,
  start_date VARCHAR(50) NOT NULL,
  end_date VARCHAR(50) NOT NULL,
  is_current BOOLEAN DEFAULT false,
  school_id VARCHAR(100) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS academic_terms (
  id VARCHAR(100) PRIMARY KEY,
  academic_year_id VARCHAR(100) NOT NULL,
  term_number INT NOT NULL,
  name VARCHAR(100) NOT NULL,
  start_date VARCHAR(50) NOT NULL,
  end_date VARCHAR(50) NOT NULL,
  is_current BOOLEAN DEFAULT false,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS classrooms (
  id VARCHAR(100) PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  grade_level VARCHAR(50) NOT NULL,
  education_level VARCHAR(50) NOT NULL,
  school_id VARCHAR(100) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS streams (
  id VARCHAR(100) PRIMARY KEY,
  classroom_id VARCHAR(100) NOT NULL,
  name VARCHAR(100) NOT NULL,
  capacity INT NOT NULL,
  class_teacher_id VARCHAR(100),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS learning_areas (
  id VARCHAR(100) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  code VARCHAR(100) NOT NULL,
  grade_level VARCHAR(50) NOT NULL,
  education_level VARCHAR(50) NOT NULL,
  is_elective BOOLEAN DEFAULT false,
  school_id VARCHAR(100) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS users (
  id VARCHAR(100) PRIMARY KEY,
  email VARCHAR(255) UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  first_name VARCHAR(100) NOT NULL,
  last_name VARCHAR(100) NOT NULL,
  role VARCHAR(50) NOT NULL,
  phone VARCHAR(50),
  status VARCHAR(50) DEFAULT 'ACTIVE',
  school_id VARCHAR(100),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS guardians (
  id VARCHAR(100) PRIMARY KEY,
  user_id VARCHAR(100),
  national_id VARCHAR(50),
  first_name VARCHAR(100) NOT NULL,
  last_name VARCHAR(100) NOT NULL,
  email VARCHAR(255),
  phone VARCHAR(50) NOT NULL,
  alternative_phone VARCHAR(50),
  occupation VARCHAR(100),
  relationship VARCHAR(50) NOT NULL,
  address TEXT,
  status VARCHAR(50) DEFAULT 'ACTIVE',
  school_id VARCHAR(100),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS students (
  id VARCHAR(100) PRIMARY KEY,
  admission_number VARCHAR(50) UNIQUE NOT NULL,
  upi_number VARCHAR(50),
  first_name VARCHAR(100) NOT NULL,
  middle_name VARCHAR(100),
  last_name VARCHAR(100) NOT NULL,
  date_of_birth VARCHAR(50) NOT NULL,
  gender VARCHAR(20) NOT NULL,
  grade_level VARCHAR(50) NOT NULL,
  classroom_id VARCHAR(100),
  stream_id VARCHAR(100),
  school_id VARCHAR(100),
  academic_year_id VARCHAR(100),
  guardian_ids JSONB DEFAULT '[]'::jsonb,
  admission_date VARCHAR(50),
  parent_phone VARCHAR(50),
  parent_email VARCHAR(255),
  residence VARCHAR(255),
  medical_conditions TEXT,
  special_needs TEXT,
  status VARCHAR(50) DEFAULT 'ACTIVE',
  profile_photo_url TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS student_guardians (
  student_id VARCHAR(100) NOT NULL,
  guardian_id VARCHAR(100) NOT NULL,
  relationship VARCHAR(50) NOT NULL,
  is_primary BOOLEAN DEFAULT false,
  is_emergency_contact BOOLEAN DEFAULT true,
  can_pickup BOOLEAN DEFAULT true,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (student_id, guardian_id)
);

CREATE TABLE IF NOT EXISTS summative_assessments (
  id VARCHAR(100) PRIMARY KEY,
  student_id VARCHAR(100) NOT NULL,
  teacher_id VARCHAR(100) NOT NULL,
  learning_area_id VARCHAR(100) NOT NULL,
  term_id VARCHAR(100) NOT NULL,
  academic_year_id VARCHAR(100) NOT NULL,
  strand_scores JSONB NOT NULL,
  overall_performance_level VARCHAR(10) NOT NULL,
  teacher_remarks TEXT NOT NULL,
  evaluation_date VARCHAR(50) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS cbc_report_cards (
  id VARCHAR(100) PRIMARY KEY,
  student_id VARCHAR(100) NOT NULL,
  term_id VARCHAR(100) NOT NULL,
  academic_year_id VARCHAR(100) NOT NULL,
  grade_level VARCHAR(50) NOT NULL,
  stream_id VARCHAR(100),
  learning_area_assessments JSONB NOT NULL,
  core_competency_assessments JSONB NOT NULL,
  value_assessments JSONB NOT NULL,
  attendance_days_present INT NOT NULL,
  attendance_days_total INT NOT NULL,
  class_teacher_remarks TEXT NOT NULL,
  head_teacher_remarks TEXT NOT NULL,
  overall_average_score NUMERIC NOT NULL,
  overall_performance_level VARCHAR(10) NOT NULL,
  closing_date VARCHAR(50),
  next_term_opening_date VARCHAR(50),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 2. INSTITUTION, ACADEMIC YEAR, TERM & CLASSROOM SETUP
VALUES ('school-001', 'Grace Seeds School', 'GSS-001', 'KIS-GSS-2026', 'The future Begins Here', 'schoolgraceseeds@gmail.com', '0745436312', 'KEMRI Street, Kisian, Kisumu, Kenya', 'KES', -0.061234, 34.721234, 250, true)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, motto = EXCLUDED.motto, email = EXCLUDED.email, phone = EXCLUDED.phone;

VALUES ('year-2026', '2026', '2026-01-05', '2026-11-20', true, 'school-001')
ON CONFLICT (id) DO UPDATE SET is_current = true;

-- CRITICAL FIX: Ensure BOTH term-2026-t3 AND term-2026-3 exist so any query format matches perfectly
ON CONFLICT (id) DO UPDATE SET is_current = EXCLUDED.is_current, name = EXCLUDED.name;

VALUES ('class-grade-3', 'Grade 3', 'GRADE_3', 'LOWER_PRIMARY', 'school-001')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, grade_level = EXCLUDED.grade_level;

VALUES ('stream-g3-main', 'class-grade-3', 'Grade 3', 45, 'teacher-sarah-mwangi')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, capacity = EXCLUDED.capacity;

-- 3. CBC GRADE 3 LEARNING AREAS
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, code = EXCLUDED.code, grade_level = EXCLUDED.grade_level;

-- 4. USERS (PARENTS/GUARDIANS) WITH PHONE AS USERNAME AND DEFAULT PASSWORD
ON CONFLICT (id) DO UPDATE SET phone = EXCLUDED.phone, password_hash = EXCLUDED.password_hash;

-- 5. GUARDIAN PROFILES (LINKED TO USER ACCOUNTS)
ON CONFLICT (id) DO UPDATE SET phone = EXCLUDED.phone, email = EXCLUDED.email;

-- 6. 21 GRADE 3 CANDIDATES
ON CONFLICT (id) DO UPDATE SET classroom_id = EXCLUDED.classroom_id, stream_id = EXCLUDED.stream_id, grade_level = EXCLUDED.grade_level;

-- STUDENT-GUARDIAN RELATIONSHIPS
ON CONFLICT (student_id, guardian_id) DO NOTHING;

-- 7. CBC SUMMATIVE ASSESSMENTS FOR ALL 8 CBC SUBJECTS
-- Migrate any pre-existing records that used term-2026-3 to also be accessible under term-2026-t3
UPDATE summative_assessments SET term_id = 'term-2026-t3' WHERE term_id = 'term-2026-3';

ON CONFLICT (id) DO UPDATE SET strand_scores = EXCLUDED.strand_scores, overall_performance_level = EXCLUDED.overall_performance_level, term_id = EXCLUDED.term_id;

-- 8. OFFICIAL CBC REPORT CARDS (TERM 3, 2026)
UPDATE cbc_report_cards SET term_id = 'term-2026-t3' WHERE term_id = 'term-2026-3';

ON CONFLICT (id) DO UPDATE SET learning_area_assessments = EXCLUDED.learning_area_assessments, overall_average_score = EXCLUDED.overall_average_score, overall_performance_level = EXCLUDED.overall_performance_level, term_id = EXCLUDED.term_id;

-- 9. DYNAMIC LINKING FOR ANY PRE-EXISTING CUSTOM LEARNING AREA UUIDS
DO $$
DECLARE
  la_rec RECORD;
  sub_key TEXT;
  sa_rec RECORD;
BEGIN
  -- For any existing Grade 3 learning areas that were assigned different IDs, ensure summatives link to them
  FOR la_rec IN (
    SELECT id, name, code FROM learning_areas 
    WHERE (grade_level = 'GRADE_3' OR grade_level = 'Grade 3')
      AND id NOT IN ('la-g3-eng', 'la-g3-rea', 'la-g3-mat', 'la-g3-kis', 'la-g3-wku', 'la-g3-senv', 'la-g3-cre', 'la-g3-crea')
  ) LOOP
    IF la_rec.name ILIKE '%Reading%' THEN sub_key := 'la-g3-rea';
    ELSIF la_rec.name ILIKE '%English%' THEN sub_key := 'la-g3-eng';
    ELSIF la_rec.name ILIKE '%Math%' THEN sub_key := 'la-g3-mat';
    ELSIF la_rec.name ILIKE '%Kusoma%' THEN sub_key := 'la-g3-wku';
    ELSIF la_rec.name ILIKE '%Kiswahili%' THEN sub_key := 'la-g3-kis';
    ELSIF la_rec.name ILIKE '%Environ%' THEN sub_key := 'la-g3-senv';
    ELSIF la_rec.name ILIKE '%Religious%' OR la_rec.name ILIKE '%Christian%' OR la_rec.code = 'CRE' THEN sub_key := 'la-g3-cre';
    ELSIF la_rec.name ILIKE '%Creative%' OR la_rec.name ILIKE '%Arts%' THEN sub_key := 'la-g3-crea';
    ELSE sub_key := NULL;
    END IF;

    IF sub_key IS NOT NULL THEN
      FOR sa_rec IN (
        SELECT student_id, strand_scores, overall_performance_level, teacher_remarks, evaluation_date 
        FROM summative_assessments 
        WHERE learning_area_id = sub_key AND term_id = 'term-2026-t3'
      ) LOOP
        VALUES (
          'sum-dyn-' || md5(sa_rec.student_id || '-' || la_rec.id || '-t3'),
          sa_rec.student_id,
          'teacher-sarah-mwangi',
          la_rec.id,
          'term-2026-t3',
          'year-2026',
          sa_rec.strand_scores,
          sa_rec.overall_performance_level,
          sa_rec.teacher_remarks,
          sa_rec.evaluation_date
        )
        ON CONFLICT (id) DO UPDATE SET strand_scores = EXCLUDED.strand_scores;
      END LOOP;
    END IF;
  END LOOP;
END $$;

COMMIT;
